#!/usr/bin/env node
/**
 * Does `types/database.generated.ts` still match the database?
 *
 * That file is hand-written. It is supposed to be generated by
 * `npm run db:types`, but `supabase gen types` shells out to Docker even when
 * given `--db-url`, and Docker is not installed here — so the file is
 * maintained by hand and nothing has ever checked it. A hand-maintained type
 * map that drifts is worse than no types: `tsc` keeps passing while the shape
 * it is checking against stops being true, and the failure surfaces at runtime
 * as a null column nobody expected.
 *
 * This is the substitute. It reads the live schema and compares table and
 * column names against what the file declares. It does not compare types —
 * a column's Postgres type and its TypeScript type are not mechanically
 * comparable without reimplementing the generator, and names are where drift
 * actually happens: a migration adds a column and the file is not updated.
 *
 *   npm run db:types:check
 *
 * Needs `SUPABASE_DB_URL` in .env.local and `psql` on PATH. Exits 0 when they
 * are absent, so it can sit in a pipeline that does not always have a database
 * — it says so rather than passing silently.
 */

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

function loadEnvLocal() {
  let raw;
  try {
    raw = readFileSync(new URL("../.env.local", import.meta.url), "utf8");
  } catch {
    return;
  }
  for (const line of raw.split("\n")) {
    const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/);
    if (m && !process.env[m[1]])
      process.env[m[1]] = m[2].replace(/^["']|["']$/g, "");
  }
}
loadEnvLocal();

const dbUrl = process.env.SUPABASE_DB_URL;
if (!dbUrl) {
  console.log("SUPABASE_DB_URL is not set — skipping the types drift check.");
  process.exit(0);
}

let rows;
try {
  rows = execFileSync(
    "psql",
    [
      dbUrl,
      "-tAF|",
      "-c",
      `select c.table_name, c.column_name
         from information_schema.columns c
         join information_schema.tables t
           on t.table_schema = c.table_schema and t.table_name = c.table_name
        where c.table_schema = 'public' and t.table_type = 'BASE TABLE'
        order by 1, 2`,
    ],
    { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
  );
} catch (err) {
  console.log(
    `Could not reach the database (${err.message.split("\n")[0]}) — skipping.`,
  );
  process.exit(0);
}

const live = new Map();
for (const line of rows.split("\n")) {
  const [table, column] = line.trim().split("|");
  if (!table || !column) continue;
  if (!live.has(table)) live.set(table, new Set());
  live.get(table).add(column);
}

const src = readFileSync(
  new URL("../types/database.generated.ts", import.meta.url),
  "utf8",
);

/**
 * Pulls each table's `Row` block. Both layouts in the file are handled — the
 * multi-line one and the single-line `Row: { a: string; b: string };` one that
 * `permissions` and `role_permissions` use. An earlier version of this check
 * only handled the first and reported those two as drifting, which is the sort
 * of false positive that gets a check switched off.
 */
const declared = new Map();
for (const m of src.matchAll(
  /\n {6}(\w+): \{\s*\n\s*Row: (\{[\s\S]*?\n?\s*\});/g,
)) {
  const cols = new Set();
  for (const c of m[2].matchAll(/[{;]\s*(\w+)\??:/g)) cols.add(c[1]);
  declared.set(m[1], cols);
}

const problems = [];

for (const table of [...live.keys()].sort()) {
  if (!declared.has(table)) problems.push(`table missing from types: ${table}`);
}
for (const table of [...declared.keys()].sort()) {
  if (!live.has(table))
    problems.push(`table in types but not in the database: ${table}`);
}
for (const table of [...live.keys()].sort()) {
  if (!declared.has(table)) continue;
  const inDb = [...live.get(table)]
    .filter((c) => !declared.get(table).has(c))
    .sort();
  const inTypes = [...declared.get(table)]
    .filter((c) => !live.get(table).has(c))
    .sort();
  if (inDb.length)
    problems.push(
      `${table}: in the database, missing from types — ${inDb.join(", ")}`,
    );
  if (inTypes.length)
    problems.push(
      `${table}: in types, not in the database — ${inTypes.join(", ")}`,
    );
}

const columnCount = [...live.values()].reduce((n, s) => n + s.size, 0);

if (problems.length === 0) {
  console.log(
    `types/database.generated.ts matches the database: ${live.size} tables, ${columnCount} columns.`,
  );
  process.exit(0);
}

console.error(
  `types/database.generated.ts has drifted from the database (${live.size} tables, ${columnCount} columns):\n`,
);
for (const p of problems) console.error(`  ${p}`);
console.error(
  "\nThe file is hand-written because `supabase gen types` needs Docker. Update it by hand,\n" +
    "or install Docker and run `npm run db:types`.",
);
process.exit(1);
